"""Meltano cron utility extension CLI entrypoint."""

from __future__ import annotations

import sys
from typing import Callable, Iterable, List, Optional

import structlog
import typer
from meltano.edk.extension import DescribeFormat
from meltano.edk.logging import default_logging_config, parse_log_level

from cron_ext import APP_NAME, Target
from cron_ext.entry import entry_pattern
from cron_ext.extension import Cron

log = structlog.get_logger(APP_NAME)

typer.core.rich = None  # remove to enable stylized help output when `rich` is installed
app = typer.Typer(
    name="cron",
    pretty_exceptions_enable=False,
)


@app.command()
def initialize(
    ctx: typer.Context,
    force: bool = typer.Option(False, help="Force initialization (if supported)"),
) -> None:
    """Initialize the cron extension (no-op)."""
    try:
        Cron().initialize(force)
    except Exception:
        log.exception(
            "initialize failed with uncaught exception, please report to maintainer"
        )
        sys.exit(1)


def _get_name_entry_pairs(entries: Iterable[str]) -> Iterable[tuple[str, str]]:
    for entry in entries:
        match = entry_pattern.fullmatch(entry)
        if match:
            yield (match["name"], entry)


def _orphaned_filter_predicate(
    ext: Cron,
    orphaned: bool | None,
) -> Callable[[str], bool]:
    if orphaned:  # only list orphaned entries for this project
        return lambda name: name not in ext.meltano_schedule_ids
    elif orphaned is False:  # only list non-orphaned entries for this project
        return lambda name: name in ext.meltano_schedule_ids
    # list all entries for this project
    return lambda _: True


@app.command(name="list")
def list_command(
    target: Target = Target.crontab,
    name_only: bool = typer.Option(
        False,
        "--name-only/--not-name-only",
        help="Whether only the names of the installed schedules should be listed",
    ),
    orphaned: Optional[bool] = typer.Option(
        None,
        "--orphaned/--not-orphaned",
        help="Schedules which are installed but unknown to Meltano are orphaned. "
        "By default all entries are listed. Use these flags to only get "
        "orphaned/non-orphaned entries.",
    ),
) -> None:
    """List installed cron entries for the Meltano project."""
    ext = Cron(store=target)

    predicate = _orphaned_filter_predicate(ext, orphaned)
    filtered_name_entry_pairs = tuple(
        (name, entry)
        for name, entry in _get_name_entry_pairs(ext.store.entries)
        if predicate(name)
    )

    entries = tuple(
        name_entry_pair[not name_only] for name_entry_pair in filtered_name_entry_pairs
    )

    if entries:
        typer.echo("\n".join(entries))


@app.command()
def install(
    schedule_ids: Optional[List[str]] = typer.Argument(None),
    target: Target = Target.crontab,
) -> None:
    """Install a crontab for the Meltano project."""
    Cron(store=target).install(set(schedule_ids or ()))


@app.command()
def uninstall(
    schedule_ids: Optional[List[str]] = typer.Argument(None),
    uninstall_all: bool = typer.Option(
        False,
        "--all",
        "-a",
        help=(
            "Uninstall all schedules, rather than just the ones from the "
            "active Meltano environment"
        ),
    ),
    target: Target = Target.crontab,
) -> None:
    """Uninstall a crontab for the Meltano project."""
    try:
        Cron(store=target).uninstall(set(schedule_ids or ()), uninstall_all)
    except ValueError as ex:
        log.error(str(ex))
        sys.exit(1)


@app.command()
def describe(
    output_format: DescribeFormat = typer.Option(
        DescribeFormat.text, "--format", help="Output format"
    )
) -> None:
    """Describe the available commands for the cron extension."""
    try:
        typer.echo(Cron().describe_formatted(output_format))
    except Exception:
        log.exception(
            "describe failed with uncaught exception, please report to maintainer"
        )
        sys.exit(1)


@app.callback(invoke_without_command=True)
def main(
    ctx: typer.Context,
    log_level: str = typer.Option("INFO", envvar="LOG_LEVEL"),
    log_timestamps: bool = typer.Option(
        False, envvar="LOG_TIMESTAMPS", help="Show timestamp in logs"
    ),
    log_levels: bool = typer.Option(
        False, "--log-levels", envvar="LOG_LEVELS", help="Show log levels"
    ),
    meltano_log_json: bool = typer.Option(
        False,
        "--meltano-log-json",
        envvar="MELTANO_LOG_JSON",
        help="Log in the meltano JSON log format",
    ),
) -> None:
    """Meltano utility extension that provides basic job scheduling via cron."""
    default_logging_config(
        level=parse_log_level(log_level),
        timestamps=log_timestamps,
        levels=log_levels,
        json_format=meltano_log_json,
    )
    if ctx.invoked_subcommand is None:
        typer.echo(ctx.get_help())

"""Cron entry store that stores entries using crontab."""

from __future__ import annotations

import os
import re
from functools import cached_property
from typing import Iterable

from cron_ext.entry import comment_pattern, entry_pattern
from cron_ext.stores.base import EntryStore
from cron_ext.subprocess import run_subprocess


class CrontabEntryStore(EntryStore):
    """Cron entry store backed by crontab."""

    is_managed = True

    def __init__(self) -> None:
        """Initialize the crontab entry store."""
        super().__init__()
        self.meltano_project_id = os.environ["MELTANO_PROJECT_ID"]

    @property
    def entries(self) -> tuple[str, ...]:
        """Entries from the installed crontab found within the Meltano section."""
        # noqa: DAR201
        lines = self.crontab.splitlines()
        try:
            a, b = self._find_meltano_section_indices(lines)
        except ValueError:
            return ()
        return tuple(line for line in lines[a:b] if not self._ignore_entry(line))

    @entries.setter
    def entries(self, new_entries: Iterable[str]) -> None:
        distinct_new_entries = tuple(self._unique_entries(new_entries))
        lines = self.crontab.splitlines()
        try:
            a, b = self._find_meltano_section_indices(lines)
        except ValueError:
            # create new Meltano section at the bottom of the crontab
            section_template = (
                "# ----- {} MELTANO CRONTAB SECTION "
                f"({self.meltano_project_id}) -----"
            )
            new_lines = (
                *lines,
                "",
                section_template.format("BEGIN"),
                *distinct_new_entries,
                section_template.format("END"),
                "",
            )
        else:
            # update the existing Meltano section
            new_lines = (
                *lines[:a],
                *distinct_new_entries,
                *lines[b:],
            )
        self.crontab = "\n".join(new_lines)

    @cached_property
    def _crontab(self) -> str:
        proc = run_subprocess(
            ("crontab", "-l"),
            "Unable to list crontab entries.",
            exit_on_nonzero_returncode=False,
        )
        return "" if proc.returncode else proc.stdout

    @property
    def crontab(self) -> str:
        """Content from the installed crontab."""
        # noqa: DAR201
        return self._crontab

    @crontab.setter
    def crontab(self, content: str) -> None:
        if not content.endswith("\n"):
            content += "\n"
        run_subprocess(
            ("crontab", "-"),
            "Unable to install new crontab.",
            input=content,
        )
        self._crontab = content

    def _index_of_match(self, pattern: str, lines: Iterable[str]) -> int:
        compiled_pattern = re.compile(pattern)
        for i, line in enumerate(lines):
            match = compiled_pattern.fullmatch(line)
            if match and match["id"] == self.meltano_project_id:
                return i
        raise ValueError(f"Pattern {pattern!r} does not match any line.")

    def _find_meltano_section_indices(self, lines: Iterable[str]) -> tuple[int, int]:
        template = r"^\s*#\s*-+\s*{} MELTANO CRONTAB SECTION \((?P<id>.*?)\)\s*-+\s*$"
        lines = tuple(lines)
        return (
            self._index_of_match(template.format("BEGIN"), lines) + 1,
            -self._index_of_match(template.format("END"), reversed(lines)) - 1,
        )

    @classmethod
    def _ignore_entry(cls, entry: str) -> bool:
        # Preserve/skip full-line comments and blank lines
        return bool(comment_pattern.fullmatch(entry)) or not entry.strip()

    @classmethod
    def _unique_entries(cls, entries: Iterable[str]) -> Iterable[str]:
        seen = set()
        for entry in entries:
            if cls._ignore_entry(entry):
                yield entry
            else:
                match = entry_pattern.fullmatch(entry)
                if not match:
                    continue
                elif match["name"] not in seen:
                    seen.add(match["name"])
                    yield entry

"""Base implementation of a cron entry store."""

from __future__ import annotations

from abc import ABCMeta, abstractmethod
from typing import Iterable


class EntryStore(metaclass=ABCMeta):
    """Abstract base class for cron entry stores."""

    @classmethod  # type: ignore
    @property
    @abstractmethod
    def is_managed(cls) -> bool:
        """Whether the store manages its entries past initial assignment."""
        ...

    @property
    @abstractmethod
    def entries(self) -> tuple[str, ...]:
        """The stored cron entries."""
        ...

    @entries.setter
    @abstractmethod
    def entries(self, new_entries: Iterable[str]) -> None: ...

"""Cron entry store that "store" by printing entries to stdout."""

from __future__ import annotations

from typing import Iterable

from cron_ext.stores.base import EntryStore


class StdoutEntryStore(EntryStore):
    """Cron entry store which emits the entries to stdout for custom handling."""

    is_managed = False

    @property
    def entries(self) -> tuple[str, ...]:
        """
        When read, returns an empty tuple, because the stdout cron entry store
        does not manage any cron entries.

        When written to, creates and prints new cron entries to stdout.
        """  # noqa
        return ()

    @entries.setter
    def entries(self, new_entries: Iterable[str]) -> None:
        print(*new_entries, sep="\n", flush=True)
